import math

def pretty_check(m, n, alpha):
    """Calculates m*ceil(n*alpha) - n*floor(m*alpha)"""
    return m * math.ceil(n * alpha) - n * math.floor(m * alpha)

alphas = {
    "sqrt2": math.sqrt(2),
    "phi": (1 + math.sqrt(5)) / 2
}

# Test up to m=5, n=5
print("--- Testing alpha = sqrt(2) ---")
for m in range(1, 6):
    for n in range(1, 6):
        result = pretty_check(m, n, alphas["sqrt2"])
        print(f"({m}, {n}): {result}")

print("\n--- Testing alpha = phi ---")
for m in range(1, 6):
    for n in range(1, 6):
        result = pretty_check(m, n, alphas["phi"])
        print(f"({m}, {n}): {result}")
